import { createClient as createClient3 } from "npm:@supabase/supabase-js@^2.103.0";
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z2 } from "npm:zod@^3.25.76";
function sb3(ctx) {
  return createClient3(process.env.SUPABASE_URL, process.env.SUPABASE_PUBLISHABLE_KEY, {
    global: { headers: { Authorization: `Bearer ${ctx.getToken()}` } },
    auth: { persistSession: false, autoRefreshToken: false }
  });
}
var list_recent_photos_default = defineTool3({
  name: "list_recent_photos",
  title: "List recent photos",
  description: "List recent photos/videos for a child, most recent first. Returns metadata (caption, taken_at, event, location) plus a 1-hour signed URL for the file and thumbnail.",
  inputSchema: {
    child_id: z2.string().uuid().describe("The child's id (from list_children)."),
    limit: z2.number().int().min(1).max(50).default(20)
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ child_id, limit }, ctx) => {
    if (!ctx.isAuthenticated())
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    const client = sb3(ctx);
    const { data, error } = await client.from("photos").select(
      "id, caption, taken_at, storage_path, thumbnail_path, media_type, duration_seconds, location_name, event_id, events(name)"
    ).eq("child_id", child_id).order("taken_at", { ascending: false }).limit(limit);
    if (error)
      return { content: [{ type: "text", text: error.message }], isError: true };
    const paths = [
      ...new Set(
        (data ?? []).flatMap(
          (p) => [p.storage_path, p.thumbnail_path].filter(Boolean)
        )
      )
    ];
    let signed = {};
    if (paths.length) {
      const { data: signedList } = await client.storage.from("photos").createSignedUrls(paths, 60 * 60);
      for (const s of signedList ?? []) {
        if (s.path && s.signedUrl) signed[s.path] = s.signedUrl;
      }
    }
    const rows = (data ?? []).map((p) => ({
      id: p.id,
      caption: p.caption,
      taken_at: p.taken_at,
      media_type: p.media_type ?? "photo",
      duration_seconds: p.duration_seconds,
      location: p.location_name,
      event_name: p.events?.name ?? null,
      url: signed[p.storage_path] ?? null,
      thumbnail_url: p.thumbnail_path ? signed[p.thumbnail_path] ?? null : null
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(rows, null, 2) }],
      structuredContent: { photos: rows }
    };
  }
});

